package com.kgsat.payment.producer; import com.kgsat.payment.model.PaymentEvent; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; @Component public class PaymentProducer { private static final Logger log=LoggerFactory.getLogger(PaymentProducer.class); private final KafkaTemplate<String,PaymentEvent> kafka; private final String topic; public PaymentProducer(KafkaTemplate<String,PaymentEvent> kafka,@Value("${app.kafka.payments-topic}") String topic){this.kafka=kafka;this.topic=topic;} public void send(PaymentEvent p){kafka.send(topic,p.orderId(),p);log.info("event=payment_published orderId={} status={}",p.orderId(),p.status());} }
